import 'dart:async';
import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:video_player/video_player.dart';

const orange = Color(0xFFFF7A00);
const dark = Color(0xFF101114);
const supabaseUrl = String.fromEnvironment('SUPABASE_URL');
const supabaseAnonKey = String.fromEnvironment('SUPABASE_ANON_KEY');

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  if (supabaseUrl.isNotEmpty && supabaseAnonKey.isNotEmpty) {
    await Supabase.initialize(url: supabaseUrl, anonKey: supabaseAnonKey);
  }
  runApp(const PikachuWorkout());
}

class PikachuWorkout extends StatelessWidget {
  const PikachuWorkout({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, title: 'Pikachu Workout', theme: ThemeData(useMaterial3: true, colorSchemeSeed: orange, scaffoldBackgroundColor: const Color(0xFFF7F7F7)),
    home: const HomeShell(),
  );
}

class Exercise { final String name; final int seconds; final int reps; final String muscle; final IconData icon; final String? video;
  const Exercise(this.name,this.seconds,this.reps,this.muscle,this.icon,[this.video]); }
final exercises = <Exercise>[
  Exercise('Jumping Jacks',20,0,'Full Body',Icons.accessibility_new), Exercise('Abdominal Crunches',0,16,'Abs',Icons.self_improvement),
  Exercise('Russian Twist',0,20,'Abs',Icons.rotate_left), Exercise('Mountain Climbers',30,0,'Core',Icons.directions_run),
  Exercise('Push Ups',0,12,'Chest',Icons.fitness_center), Exercise('Bodyweight Squats',30,0,'Legs',Icons.airline_seat_legroom_normal),
  Exercise('Lunges',24,0,'Legs & Glutes',Icons.directions_walk), Exercise('Plank',30,0,'Core',Icons.horizontal_rule),
  Exercise('High Knees',30,0,'Cardio',Icons.directions_run), Exercise('Glute Bridge',20,0,'Glutes',Icons.accessibility),
  Exercise('Triceps Dips',0,12,'Arms',Icons.chair), Exercise('Arm Circles',20,0,'Shoulders',Icons.sync),
];

