class ExerciseAnimation extends StatefulWidget { final Exercise exercise; const ExerciseAnimation({super.key,required this.exercise}); @override State<ExerciseAnimation> createState()=>_ExerciseAnimationState(); }
class _ExerciseAnimationState extends State<ExerciseAnimation> with SingleTickerProviderStateMixin {late AnimationController c;@override void initState(){super.initState();c=AnimationController(vsync:this,duration:const Duration(milliseconds:800))..repeat(reverse:true);}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext x)=>AnimatedBuilder(animation:c,builder:(_,__)=>Container(width:300,height:300,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(30)),child:CustomPaint(painter:WorkoutPainter(c.value,widget.exercise.name))));}
class WorkoutPainter extends CustomPainter {final double t;final String name;WorkoutPainter(this.t,this.name);@override void paint(Canvas p,Size s){final q=Paint()..strokeWidth=12..strokeCap=StrokeCap.round..style=PaintingStyle.stroke..color=dark;final f=Paint()..color=orange;final cx=s.width/2, y=95+(name.contains('Squat')?t*30:0);p.drawCircle(Offset(cx,y),25,f);p.drawLine(Offset(cx,y+28),Offset(cx,y+115),q);final spread=name.contains('Jack')?35+70*t:25;p.drawLine(Offset(cx,y+45),Offset(cx-spread,y+75),q);p.drawLine(Offset(cx,y+45),Offset(cx+spread,y+75),q);p.drawLine(Offset(cx,y+115),Offset(cx-45,y+190),q);p.drawLine(Offset(cx,y+115),Offset(cx+45,y+190),q);p.drawCircle(Offset(cx,y+40),10,f);} @override bool shouldRepaint(c)=>true;}

class VideoPanel extends StatefulWidget {final String? url;const VideoPanel({super.key,this.url});@override State<VideoPanel> createState()=>_VideoPanelState();}
class _VideoPanelState extends State<VideoPanel>{VideoPlayerController? v;@override void initState(){super.initState();if(widget.url!=null&&widget.url!.isNotEmpty){v=VideoPlayerController.networkUrl(Uri.parse(widget.url!))..initialize().then((_){setState((){});});}}@override void dispose(){v?.dispose();super.dispose();}@override Widget build(BuildContext c){if(v==null)return const Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.video_library_outlined,size:60,color:orange),SizedBox(height:10),Text('Exercise video will appear here',style:TextStyle(color:Colors.grey))]);if(!v!.value.isInitialized)return const Center(child:CircularProgressIndicator());return Stack(alignment:Alignment.center,children:[AspectRatio(aspectRatio:v!.value.aspectRatio,child:VideoPlayer(v!)),IconButton.filled(onPressed:()=>setState(()=>v!.value.isPlaying?v!.pause():v!.play()),icon:Icon(v!.value.isPlaying?Icons.pause:Icons.play_arrow))]);}}

class WorkoutPlayer extends StatefulWidget {final List<Exercise> list;const WorkoutPlayer({super.key,required this.list});@override State<WorkoutPlayer> createState()=>_WorkoutPlayerState();}
class _WorkoutPlayerState extends State<WorkoutPlayer>{int i=0,left=20;Timer? timer;bool running=false;@override void initState(){super.initState();start();}void start(){timer?.cancel();running=true;left=widget.list[i].seconds>0?widget.list[i].seconds:30;timer=Timer.periodic(const Duration(seconds:1),(_){if(!mounted)return;if(left<=1){if(i<widget.list.length-1){setState(()=>i++);left=widget.list[i].seconds>0?widget.list[i].seconds:30;}else{timer?.cancel();setState(()=>running=false);showDone();}}else setState(()=>left--);});}void showDone()=>showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Workout Complete 🎉'),content:const Text('Great work! Your session has been completed.'),actions:[TextButton(onPressed:()=>Navigator.popUntil(context,(r)=>r.isFirst),child:const Text('DONE'))]));@override void dispose(){timer?.cancel();super.dispose();}@override Widget build(BuildContext c){final e=widget.list[i];return Scaffold(backgroundColor:dark,appBar:AppBar(backgroundColor:dark,foregroundColor:Colors.white,title:Text('${i+1}/${widget.list.length}')),body:Column(children:[Expanded(child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[ExercisePreview(exercise:e,size:230),const SizedBox(height:35),Text(e.name,style:const TextStyle(color:Colors.white,fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:20),Text(e.reps>0?'× ${e.reps}':'${left}s',style:const TextStyle(color:orange,fontSize:64,fontWeight:FontWeight.w900))])),LinearProgressIndicator(value:(i+1)/widget.list.length,minHeight:7,color:orange),Padding(padding:const EdgeInsets.all(20),child:Row(children:[Expanded(child:OutlinedButton(onPressed:()=>setState(()=>running=!running),child:Text(running?'PAUSE':'RESUME'))),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:(){if(i<widget.list.length-1){setState(()=>i++);start();}},child:const Text('SKIP')))]))]));}}

